 @Test public void nativeExtractorDownloadsAuthorizedLocalAudio()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();byte[] bytes;try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.wav");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);bytes=out.toByteArray();}ServerSocket server=new ServerSocket(0,10,InetAddress.getByName("127.0.0.1"));AtomicBoolean stop=new AtomicBoolean();Thread thread=new Thread(()->{while(!stop.get())try(Socket sock=server.accept()){sock.setSoTimeout(10000);BufferedReader reader=new BufferedReader(new InputStreamReader(sock.getInputStream()));String first=reader.readLine(),line;while((line=reader.readLine())!=null&&!line.isEmpty()){}OutputStream out=sock.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: "+bytes.length+"\r\nContent-Disposition: inline; filename=\"sample.wav\"\r\nConnection: close\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.US_ASCII));if(first!=null&&first.startsWith("GET"))out.write(bytes);out.flush();}catch(Exception ignored){}});thread.start();String url="http://127.0.0.1:"+server.getLocalPort()+"/sample.wav";Store.Job job=null;try{MediaEngine.Result r=MediaEngine.analyze(c,url);MediaEngine.Choice chosen=null;for(MediaEngine.Choice x:r.choices)if(x.audio&&!x.mp3&&x.ext.equals("wav")){chosen=x;break;}assertNotNull("Original WAV option missing; "+r.choices.stream().map(x->x.label+" / "+x.selector).collect(java.util.stream.Collectors.joining(", ")),chosen);job=new Store.Job(url,new HttpEngine.Info("sample.wav","audio/wav",chosen.size,"","",false),"");job.selector=chosen.selector;job.extension=chosen.ext;File output=MediaEngine.transfer(c,job,new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long a,long b,String e,String m){}});assertNotNull(output);assertArrayEquals(bytes,java.nio.file.Files.readAllBytes(output.toPath()));}finally{if(job!=null)MediaEngine.cleanup(c,job.id);stop.set(true);server.close();thread.join(2000);}}
 @Test public void independentConcurrentDownloads()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();byte[] data=new byte[400000];new java.util.Random(71).nextBytes(data);ServerSocket server=new ServerSocket(0,10,InetAddress.getByName("127.0.0.1"));AtomicBoolean stop=new AtomicBoolean();java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(4);java.util.concurrent.CountDownLatch both=new java.util.concurrent.CountDownLatch(2);Thread thread=new Thread(()->{while(!stop.get())try{Socket sock=server.accept();pool.execute(()->{try(Socket conn=sock){conn.setSoTimeout(10000);BufferedReader reader=new BufferedReader(new InputStreamReader(conn.getInputStream()));String first=reader.readLine(),line;while((line=reader.readLine())!=null&&!line.isEmpty()){}if(first!=null&&first.startsWith("GET")){both.countDown();both.await(8,java.util.concurrent.TimeUnit.SECONDS);}OutputStream out=conn.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n").getBytes());if(first!=null&&first.startsWith("GET"))out.write(data);out.flush();}catch(Exception ignored){}});}catch(Exception ignored){}});thread.start();Store.settings(c).edit().putBoolean("http",true).putBoolean("wifi",false).putBoolean("battery",false).putInt("parallel_jobs",2).putInt("mode",1).commit();String url="http://127.0.0.1:"+server.getLocalPort();Store.Job a=new Store.Job(url+"/one.bin",new HttpEngine.Info("one.bin","application/octet-stream",data.length,"","",false),""),b=new Store.Job(url+"/two.bin",new HttpEngine.Info("two.bin","application/octet-stream",data.length,"","",false),"");Store.get(c).add(a);Store.get(c).add(b);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(v->TransferService.command(v,"start",a.id));assertTrue("Both GET requests must overlap",both.await(7,java.util.concurrent.TimeUnit.SECONDS));long end=android.os.SystemClock.elapsedRealtime()+30000;while(android.os.SystemClock.elapsedRealtime()<end&&!a.state.equals("error")&&!b.state.equals("error")&&(!a.state.equals("complete")||!b.state.equals("complete")))Thread.sleep(100);assertEquals(a.error,"complete",a.state);assertEquals(b.error,"complete",b.state);assertEquals(a.sha,b.sha);assertEquals(data.length,a.done);assertEquals(data.length,b.done);}finally{stop.set(true);server.close();pool.shutdownNow();thread.join(2000);for(Store.Job j:new Store.Job[]{a,b})if(!j.uri.isEmpty())c.getContentResolver().delete(Uri.parse(j.uri),null,null);c.stopService(new Intent(c,TransferService.class));Store.settings(c).edit().clear().commit();}}
