 static final class FixtureServer implements AutoCloseable{
  final File dir;final ServerSocket socket;final java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(8);final Thread accept;volatile boolean dead;final java.util.concurrent.atomic.AtomicInteger gets=new java.util.concurrent.atomic.AtomicInteger();
  FixtureServer(File dir)throws Exception{this.dir=dir;socket=new ServerSocket(0,12,InetAddress.getByName("127.0.0.1"));accept=new Thread(()->{while(!dead)try{Socket client=socket.accept();pool.execute(()->serve(client));}catch(Exception ignored){}});accept.start();}
  String url(String path){return "http://127.0.0.1:"+socket.getLocalPort()+"/"+path;}
  void serve(Socket client){try(Socket s=client){s.setSoTimeout(10000);BufferedReader reader=new BufferedReader(new InputStreamReader(s.getInputStream()));String first=reader.readLine(),line,range="";if(first==null)return;for(int i=0;i<100&&(line=reader.readLine())!=null&&!line.isEmpty();i++)if(line.toLowerCase(java.util.Locale.ROOT).startsWith("range:"))range=line.substring(6).trim();String[] fields=first.split(" ");if(fields.length<2)return;String path=Uri.parse(fields[1]).getPath();File f=new File(dir,path.startsWith("/")?path.substring(1):path);OutputStream out=s.getOutputStream();if(!f.isFile()||!f.getCanonicalPath().startsWith(dir.getCanonicalPath()+File.separator)){out.write("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes());return;}long size=f.length(),start=0,end=size-1;boolean partial=false;if(range.matches("bytes=\\d+-\\d*")){String[] x=range.substring(6).split("-", -1);start=Long.parseLong(x[0]);if(!x[1].isEmpty())end=Math.min(end,Long.parseLong(x[1]));partial=true;}if(start>end){out.write(("HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */"+size+"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").getBytes());return;}String name=f.getName(),mime=name.endsWith(".m3u8")?"application/vnd.apple.mpegurl":name.endsWith(".mpd")?"application/dash+xml":name.endsWith(".ts")?"video/mp2t":name.endsWith(".m4s")?"video/iso.segment":name.endsWith(".mp4")?"video/mp4":"application/octet-stream";out.write(("HTTP/1.1 "+(partial?"206 Partial Content":"200 OK")+"\r\nContent-Type: "+mime+"\r\nContent-Length: "+(end-start+1)+"\r\nAccept-Ranges: bytes\r\n"+(partial?"Content-Range: bytes "+start+"-"+end+"/"+size+"\r\n":"")+"Connection: close\r\n\r\n").getBytes());if(fields[0].equals("GET")){gets.incrementAndGet();try(RandomAccessFile in=new RandomAccessFile(f,"r")){in.seek(start);long left=end-start+1;byte[] b=new byte[32768];while(left>0){int n=in.read(b,0,(int)Math.min(left,b.length));if(n<0)break;out.write(b,0,n);left-=n;}}}out.flush();}catch(Exception ignored){}}
  public void close()throws IOException{dead=true;socket.close();pool.shutdownNow();try{accept.join(2000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
 }
 static void ffmpeg(String... args)throws IOException{NativeMedia.run(InstrumentationRegistry.getInstrumentation().getTargetContext(),args);}
 @Test public void authorizedHlsAndDashActualDownload()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(c.getCacheDir(),"streams-"+java.util.UUID.randomUUID());assertTrue(root.mkdirs());File wav=new File(root,"sample.wav");try{try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.wav");OutputStream out=new FileOutputStream(wav)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}File hls=new File(root,"hls"),dash=new File(root,"dash");assertTrue(hls.mkdir());assertTrue(dash.mkdir());ffmpeg("-y","-i",wav.getPath(),"-c:a","aac","-f","hls","-hls_time","1","-hls_list_size","0","-hls_segment_filename",new File(hls,"seg%d.ts").getPath(),new File(hls,"index.m3u8").getPath());ffmpeg("-y","-i",wav.getPath(),"-c:a","aac","-f","dash","-seg_duration","1",new File(dash,"index.mpd").getPath());try(FixtureServer server=new FixtureServer(root)){for(String path:new String[]{"hls/index.m3u8","dash/index.mpd"}){String url=server.url(path);MediaEngine.Result r=MediaEngine.analyze(c,url);MediaEngine.Choice choice=null;for(MediaEngine.Choice x:r.choices)if(x.mp3&&MediaEngine.mp3Rate(x)==128){choice=x;break;}assertNotNull("MP3 conversion missing for "+path,choice);Store.Job job=new Store.Job(url,new HttpEngine.Info("stream.mp3","audio/mpeg",choice.size,"","",false),"");job.selector=choice.selector;job.extension="mp3";job.mp3Rate=128;try{File out=MediaEngine.transfer(c,job,new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long a,long b,String e,String m){}});assertNotNull(out);assertTrue(out.length()>100);android.media.MediaMetadataRetriever mm=new android.media.MediaMetadataRetriever();try{mm.setDataSource(out.getPath());long duration=Long.parseLong(mm.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION));assertTrue(path+" duration "+duration,duration>=1500&&duration<=2600);}finally{mm.release();}}finally{MediaEngine.cleanup(c,job.id);}}assertTrue(server.gets.get()>4);}}finally{FileTools.deleteTree(root);}}
 static void bstr(ByteArrayOutputStream out,String s)throws Exception{bstr(out,s.getBytes(java.nio.charset.StandardCharsets.UTF_8));}static void bstr(ByteArrayOutputStream out,byte[] data)throws Exception{out.write((data.length+":").getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.write(data);}
 @Test public void nativeTorrentActualWebSeedTransfer()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(c.getCacheDir(),"torrent-fixture-"+java.util.UUID.randomUUID());assertTrue(root.mkdirs());byte[] content=new byte[65536];new java.util.Random(31).nextBytes(content);java.nio.file.Files.write(new File(root,"payload.bin").toPath(),content);Store.Job j=new Store.Job("torrent:local",new HttpEngine.Info("Torrent","application/octet-stream",-1,"","",false),"");j.torrent=true;try(FixtureServer server=new FixtureServer(root)){File dir=TorrentEngine.folder(c,j.id);assertTrue(dir.mkdirs());ByteArrayOutputStream meta=new ByteArrayOutputStream();meta.write('d');bstr(meta,"info");meta.write('d');bstr(meta,"length");meta.write(("i"+content.length+"e").getBytes());bstr(meta,"name");bstr(meta,"payload.bin");bstr(meta,"piece length");meta.write("i16384e".getBytes());bstr(meta,"pieces");ByteArrayOutputStream hashes=new ByteArrayOutputStream();for(int n=0;n<content.length;n+=16384)hashes.write(java.security.MessageDigest.getInstance("SHA-1").digest(java.util.Arrays.copyOfRange(content,n,n+16384)));bstr(meta,hashes.toByteArray());meta.write('e');bstr(meta,"url-list");bstr(meta,server.url("payload.bin"));meta.write('e');java.nio.file.Files.write(TorrentEngine.input(c,j.id).toPath(),meta.toByteArray());long deadline=android.os.SystemClock.elapsedRealtime()+60000;File out=TorrentEngine.transfer(c,j,new HttpEngine.Observer(){public boolean proceed(){return android.os.SystemClock.elapsedRealtime()<deadline;}public void progress(long a,long b,String e,String m){}});assertNotNull("Torrent webseed transfer timed out",out);assertArrayEquals(content,java.nio.file.Files.readAllBytes(out.toPath()));assertTrue(server.gets.get()>0);}finally{TorrentEngine.cleanup(c,j.id);FileTools.deleteTree(root);}}
 @Test public void scheduledQueueSurvivesViaSystemJob()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store store=Store.get(c);long now=System.currentTimeMillis();Store.Job j=new Store.Job("https://example.org/file",new HttpEngine.Info("schedule.bin","application/octet-stream",1,"","",false),"");j.state="scheduled";j.notBefore=now+600000;store.add(j);try{ScheduleService.arm(c);android.app.job.JobInfo job=c.getSystemService(android.app.job.JobScheduler.class).getPendingJob(ScheduleService.JOB);assertNotNull(job);assertTrue(job.isPersisted());assertTrue(ScheduleService.next(store,now)<=j.notBefore);}finally{store.remove(j);c.getSystemService(android.app.job.JobScheduler.class).cancel(ScheduleService.JOB);}}
 @Test public void audioStudioRealConversions()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File in=File.createTempFile("studio-fixture-",".wav",c.getCacheDir());try{try{AudioStudioActivity.stage(new ByteArrayInputStream(new byte[0]),in);fail("Empty source must be rejected");}catch(IOException expected){assertTrue(expected.getMessage().contains("empty"));}try(InputStream input=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.wav")){AudioStudioActivity.stage(input,in);}assertTrue(in.length()>44);for(String fmt:new String[]{"flac","wav","m4a","opus","aac","mp3"}){File out=File.createTempFile("studio-test-","."+fmt,c.getCacheDir());try{AudioStudioActivity.encode(c,in,out,fmt,128,"Original fixture","X Download",0.25,1.25);assertTrue(fmt,out.length()>44);android.media.MediaMetadataRetriever mm=new android.media.MediaMetadataRetriever();try{mm.setDataSource(out.getPath());String dur=mm.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION);if(dur!=null){long d=Long.parseLong(dur);assertTrue(fmt+" duration "+d,d>=700&&d<=1500);}}finally{mm.release();}}finally{out.delete();}}}finally{in.delete();}}
 @Test public void safeCacheCleanupOnlyRemovesKnownOldFiles()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File dir=new File(c.getCacheDir(),"audit-test-"+java.util.UUID.randomUUID());assertTrue(dir.mkdirs());long now=System.currentTimeMillis();File old=new File(dir,"studio-in-old.tmp"),recent=new File(dir,"studio-in-recent.tmp"),unknown=new File(dir,"unrelated.tmp");try{for(File file:new File[]{old,recent,unknown})java.nio.file.Files.write(file.toPath(),new byte[]{1,2,3});assertTrue(old.setLastModified(now-StorageAudit.STALE-10000));assertTrue(unknown.setLastModified(now-StorageAudit.STALE-10000));assertEquals(3,StorageAudit.stale(dir,false,now));assertEquals(3,StorageAudit.stale(dir,true,now));assertFalse(old.exists());assertTrue(recent.exists());assertTrue(unknown.exists());assertEquals(6,StorageAudit.bytes(dir));assertTrue(StorageAudit.measure(c).apk>0);}finally{FileTools.deleteTree(dir);}}

 @Test public void localPlayerPlaysSyntheticAudioAndRepeatPolicy()throws Exception{
  assertEquals(1,LocalPlayerActivity.nextIndex(0,2,0,true));
  assertEquals(-1,LocalPlayerActivity.nextIndex(1,2,0,true));
  assertEquals(1,LocalPlayerActivity.nextIndex(1,2,1,true));
  assertEquals(0,LocalPlayerActivity.nextIndex(1,2,2,true));
  Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
  ContentValues values=new ContentValues();
  values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"xdownload-player-"+java.util.UUID.randomUUID()+".wav");
  values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"audio/wav");
  values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,android.os.Environment.DIRECTORY_DOWNLOADS+"/XDownloadPro/Test");
  values.put(android.provider.MediaStore.MediaColumns.IS_PENDING,1);
  Uri uri=c.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);assertNotNull(uri);
  Store.Job job=new Store.Job("https://example.invalid/local-test.wav",new HttpEngine.Info("local-test.wav","audio/wav",176400,"","",false),"");
  try{
   try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.wav");OutputStream out=c.getContentResolver().openOutputStream(uri,"w")){AudioStudioActivity.copy(in,out);}
   ContentValues done=new ContentValues();done.put(android.provider.MediaStore.MediaColumns.IS_PENDING,0);assertEquals(1,c.getContentResolver().update(uri,done,null,null));
   job.uri=uri.toString();job.state="complete";Store.get(c).add(job);assertTrue(LocalPlayerActivity.playable(job));job.favorite=true;assertTrue(new Store.Job(job.json()).favorite);assertFalse(MainActivity.canRenew(job));
   Intent intent=new Intent(c,LocalPlayerActivity.class).putExtra("job_id",job.id);
   try(ActivityScenario<LocalPlayerActivity> scenario=ActivityScenario.launch(intent)){
    AtomicBoolean prepared=new AtomicBoolean(false),playing=new AtomicBoolean(false);
    long until=android.os.SystemClock.elapsedRealtime()+12000;
    while(android.os.SystemClock.elapsedRealtime()<until&&!playing.get()){
     scenario.onActivity(a->{if(a.ready&&a.video.getDuration()>=1800)prepared.set(true);if(a.ready&&a.video.isPlaying())playing.set(true);});
     if(!playing.get())Thread.sleep(100);
    }
    assertTrue("Local WAV must prepare",prepared.get());assertTrue("Local WAV must play",playing.get());
    scenario.onActivity(a->{a.pausePlayback();BackgroundAudioService.launch(a,job.id,0);});
    scenario.moveToState(androidx.lifecycle.Lifecycle.State.CREATED);
    long audioUntil=android.os.SystemClock.elapsedRealtime()+10000;
    while(android.os.SystemClock.elapsedRealtime()<audioUntil&&!BackgroundAudioService.playingForTest)Thread.sleep(50);
    assertTrue("Background audio must actually play",BackgroundAudioService.playingForTest);
    assertEquals(job.id,BackgroundAudioService.currentId);
    c.stopService(new Intent(c,BackgroundAudioService.class));
   }
  }finally{c.stopService(new Intent(c,BackgroundAudioService.class));Store.get(c).remove(job);c.getContentResolver().delete(uri,null,null);}
 }

 @Test public void offlineReaderRoundTripAndSettingsSearch()throws Exception{
  Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
  String marker="test-"+java.util.UUID.randomUUID();String id=null;
  try{OfflinePages.save(c,marker,"https://example.invalid/reader","Plain text fixture");for(OfflinePages.Page p:OfflinePages.list(c))if(marker.equals(p.title)){id=p.id;assertEquals("Plain text fixture",p.text);}assertNotNull(id);OfflinePages.delete(c,id);for(OfflinePages.Page p:OfflinePages.list(c))assertFalse(marker.equals(p.title));}
  finally{if(id!=null)OfflinePages.delete(c,id);}
  try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->{a.show(4);MainActivity.filterSettings(a.body,"JavaScript");int visible=0;for(int i=2;i<a.body.getChildCount();i++)if(a.body.getChildAt(i).getVisibility()==android.view.View.VISIBLE)visible++;assertEquals(1,visible);MainActivity.filterSettings(a.body,"");for(int i=2;i<a.body.getChildCount();i++)assertEquals(android.view.View.VISIBLE,a.body.getChildAt(i).getVisibility());});}
 }

 @Test public void actualVideoImagesAndEncryptedSettings()throws Exception{
  Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File dir=new File(c.getCacheDir(),"angel-test-"+java.util.UUID.randomUUID());assertTrue(dir.mkdir());
  SharedPreferences prefs=c.getSharedPreferences("angel-backup-test",0);
  try{
   File raw=new File(dir,"frames.rgb"),video=new File(dir,"sample.mp4"),png=new File(dir,"frame.png"),gif=new File(dir,"clip.gif");
   try(OutputStream out=new FileOutputStream(raw)){byte[] frame=new byte[64*48*3];for(int n=0;n<20;n++){for(int k=0;k<frame.length;k+=3){frame[k]=(byte)(n*9);frame[k+1]=(byte)(k%255);frame[k+2]=(byte)127;}out.write(frame);}}
   ffmpeg("-y","-f","rawvideo","-pixel_format","rgb24","-video_size","64x48","-framerate","10","-i",raw.getPath(),"-c:v","mpeg4","-pix_fmt","yuv420p",video.getPath());
   VideoImageActivity.encode(c,video,png,0.2,0,false);VideoImageActivity.encode(c,video,gif,0,1,true);assertTrue(png.length()>32);assertTrue(gif.length()>32);File converted=new File(dir,"compressed.mp4");BatchVideoActivity.encode(c,video,converted,480,10);assertTrue(converted.length()>100);assertTrue(converted.length()<10L*1024*1024);
   prefs.edit().putInt("connections",16).putString("private_url","must-not-export").commit();
   org.json.JSONObject saved=SettingsBackupActivity.snapshot(prefs);assertFalse(saved.has("private_url"));
   File clear=new File(dir,"settings.json"),enc=new File(dir,"settings.xdvault"),decoded=new File(dir,"decoded.json");
   java.nio.file.Files.write(clear.toPath(),saved.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
   FileTools.crypt(clear,enc,"test-password".toCharArray(),true);FileTools.crypt(enc,decoded,"test-password".toCharArray(),false);
   prefs.edit().clear().commit();SettingsBackupActivity.apply(prefs,new org.json.JSONObject(new String(java.nio.file.Files.readAllBytes(decoded.toPath()),java.nio.charset.StandardCharsets.UTF_8)));assertEquals(16,prefs.getInt("connections",0));assertFalse(prefs.contains("private_url"));
  }finally{prefs.edit().clear().commit();FileTools.deleteTree(dir);}
 }

 @Test public void sevenZipRealExtractionAndTraversalRejection()throws Exception{
  Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File dir=new File(c.getCacheDir(),"archive-test-"+java.util.UUID.randomUUID());assertTrue(dir.mkdir());try{
   byte[] payload=new byte[32768];new java.util.Random(41).nextBytes(payload);File input=new File(dir,"payload.bin"),archive=new File(dir,"sample.7z");java.nio.file.Files.write(input.toPath(),payload);
   try(org.apache.commons.compress.archivers.sevenz.SevenZOutputFile z=new org.apache.commons.compress.archivers.sevenz.SevenZOutputFile(archive)){z.putArchiveEntry(z.createArchiveEntry(input,"folder/payload.bin"));z.write(payload);z.closeArchiveEntry();}
   File extracted=new File(dir,"extracted");assertEquals(1,ArchiveTools.extract(archive,extracted));assertArrayEquals(payload,java.nio.file.Files.readAllBytes(new File(extracted,"folder/payload.bin").toPath()));
   File rar=new File(dir,"sample.rar");writeStoredRar(rar,"payload.bin",payload);File rarOut=new File(dir,"rar-out");assertEquals(1,ArchiveTools.extract(rar,rarOut));assertArrayEquals(payload,java.nio.file.Files.readAllBytes(new File(rarOut,"payload.bin").toPath()));
   File badRar=new File(dir,"bad.rar");writeStoredRar(badRar,"../escape",payload);try{ArchiveTools.extract(badRar,new File(dir,"bad-rar-out"));fail("RAR traversal must be rejected");}catch(IOException expected){assertFalse(new File(dir,"escape").exists());}
   File bad=new File(dir,"bad.7z");try(org.apache.commons.compress.archivers.sevenz.SevenZOutputFile z=new org.apache.commons.compress.archivers.sevenz.SevenZOutputFile(bad)){z.putArchiveEntry(z.createArchiveEntry(input,"../escape"));z.write(payload);z.closeArchiveEntry();}
   try{ArchiveTools.extract(bad,new File(dir,"bad-out"));fail("Traversal must be rejected");}catch(IOException expected){assertFalse(new File(dir,"escape").exists());}
  }finally{FileTools.deleteTree(dir);}
 }

 static void little(ByteArrayOutputStream out,long n,int bytes){for(int i=0;i<bytes;i++)out.write((int)(n>>>(8*i))&255);}
 static void rarHeader(OutputStream out,byte[] body)throws IOException{java.util.zip.CRC32 crc=new java.util.zip.CRC32();crc.update(body);int v=(int)crc.getValue();out.write(v&255);out.write((v>>>8)&255);out.write(body);}
 /** Synthetic RAR4 store-method fixture; no third-party copyrighted payload. */
 static void writeStoredRar(File file,String name,byte[] data)throws IOException{byte[] filename=name.getBytes(java.nio.charset.StandardCharsets.US_ASCII);java.util.zip.CRC32 content=new java.util.zip.CRC32();content.update(data);try(OutputStream out=new FileOutputStream(file)){
  out.write(new byte[]{0x52,0x61,0x72,0x21,0x1a,0x07,0});
  ByteArrayOutputStream main=new ByteArrayOutputStream();main.write(0x73);little(main,0,2);little(main,13,2);little(main,0,2);little(main,0,4);rarHeader(out,main.toByteArray());
  ByteArrayOutputStream header=new ByteArrayOutputStream();header.write(0x74);little(header,0x8000,2);little(header,32+filename.length,2);little(header,data.length,4);little(header,data.length,4);header.write(2);little(header,content.getValue(),4);little(header,0,4);header.write(20);header.write(0x30);little(header,filename.length,2);little(header,0x20,4);header.write(filename);rarHeader(out,header.toByteArray());out.write(data);
  ByteArrayOutputStream end=new ByteArrayOutputStream();end.write(0x7b);little(end,0,2);little(end,7,2);rarHeader(out,end.toByteArray());
 }}

 @Test public void mediaStoreTrashRestoresOriginalBytes()throws Exception{
  Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();if(android.os.Build.VERSION.SDK_INT<30)return;
  byte[] payload=new byte[16384];new java.util.Random(17).nextBytes(payload);android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"trash-test-"+java.util.UUID.randomUUID()+".bin");v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"application/octet-stream");v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,android.os.Environment.DIRECTORY_DOWNLOADS+"/XDownloadPro/Test");v.put(android.provider.MediaStore.MediaColumns.IS_PENDING,1);
  Uri uri=c.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);assertNotNull(uri);try{try(OutputStream out=c.getContentResolver().openOutputStream(uri,"w")){assertNotNull(out);out.write(payload);}android.content.ContentValues ready=new android.content.ContentValues();ready.put(android.provider.MediaStore.MediaColumns.IS_PENDING,0);assertEquals(1,c.getContentResolver().update(uri,ready,null,null));TrashManager.change(c,uri,true);assertTrue(TrashManager.state(c,uri));TrashManager.change(c,uri,false);assertFalse(TrashManager.state(c,uri));ByteArrayOutputStream result=new ByteArrayOutputStream();try(InputStream in=c.getContentResolver().openInputStream(uri)){AudioStudioActivity.copy(in,result);}assertArrayEquals(payload,result.toByteArray());}finally{try{TrashManager.change(c,uri,false);}catch(Exception ignored){}c.getContentResolver().delete(uri,null,null);}
 }
